from typing import List


class Solution:
    def shipWithinDays(self, weights: List[int], days: int) -> int:
        def days_needed(capacity):
            used, load = 1, 0
            for w in weights:
                if load + w > capacity:
                    used += 1
                    load = 0
                load += w
            return used

        left, right = max(weights), sum(weights)
        while left < right:
            mid = (left + right) // 2
            if days_needed(mid) <= days:
                right = mid
            else:
                left = mid + 1
        return left

