def need(w, cap):
    used, load = 1, 0
    for x in w:
        if load + x > cap:
            used += 1
            load = 0
        load += x
    return used

def brute(w, days):
    return next(cap for cap in range(max(w), sum(w) + 1) if need(w, cap) <= days)

check(S, "shipWithinDays", gen, brute)

