class Solution:
    def splitArray(self, nums: List[int], k: int) -> int:
        def parts_needed(limit):
            parts, cur = 1, 0
            for x in nums:
                if cur + x > limit:
                    parts += 1
                    cur = 0
                cur += x
            return parts

        left, right = max(nums), sum(nums)
        while left < right:
            mid = (left + right) // 2
            if parts_needed(mid) <= k:
                right = mid
            else:
                left = mid + 1
        return left

